import { type AIConfig, customQuery, getAIConfig } from '@intlayer/ai';
import { logger } from '@logger';
import { getProjectAIOptions } from '@utils/AI/getProjectAIOptions';
import type { Project } from '@/types/project.types';

/** Most commitlint setups cap the header at 100 characters */
export const COMMIT_SUBJECT_MAX_LENGTH = 100;

/** `type(scope)!: subject` */
const CONVENTIONAL_COMMIT_PATTERN = /^[a-z]+(\([^)]*\))?!?: \S/;

/** Commits generated by git itself say nothing about the team's style */
const GENERATED_COMMIT_PATTERN = /^(Merge|Revert ")/;

/** Maximum characters of file changes sent to the AI */
const MAX_CHANGES_PROMPT_LENGTH = 4000;

const AI_DEFAULT_OPTIONS = { model: 'gpt-4o-mini' };

export type CommitStyle = {
  /** Subjects follow `type(scope): subject` */
  isConventional: boolean;
  /** Subjects (after the conventional prefix) start with an upper case */
  isCapitalized: boolean;
};

export type CommitFileChange = {
  dictionaryKey: string;
  path: string;
  previousContent: string;
  nextContent: string;
};

const stripConventionalPrefix = (subject: string): string =>
  subject.replace(/^[a-z]+(\([^)]*\))?!?: /, '');

/**
 * Infers the commit subject style from the latest commits of the branch.
 */
export const detectCommitStyle = (recentSubjects: string[]): CommitStyle => {
  const subjects = recentSubjects
    .map((subject) => subject.trim())
    .filter(
      (subject) => subject !== '' && !GENERATED_COMMIT_PATTERN.test(subject)
    );

  if (subjects.length === 0) {
    return { isConventional: false, isCapitalized: false };
  }

  const conventionalCount = subjects.filter((subject) =>
    CONVENTIONAL_COMMIT_PATTERN.test(subject)
  ).length;

  const capitalizedCount = subjects.filter((subject) =>
    /^[A-Z]/.test(stripConventionalPrefix(subject))
  ).length;

  return {
    isConventional: conventionalCount * 2 >= subjects.length,
    isCapitalized: capitalizedCount * 2 > subjects.length,
  };
};

const applyStyle = (description: string, style: CommitStyle): string => {
  const casedDescription = style.isCapitalized
    ? description.charAt(0).toUpperCase() + description.slice(1)
    : description.charAt(0).toLowerCase() + description.slice(1);

  return style.isConventional ? `feat: ${casedDescription}` : casedDescription;
};

/**
 * Builds `feat: update dictionaries 'a', 'b'`, listing as many keys as the
 * subject length allows and summing up the rest.
 */
export const buildGenericCommitMessage = (
  dictionaryKeys: string[],
  style: CommitStyle
): string => {
  const uniqueKeys = [...new Set(dictionaryKeys)];
  const prefix = applyStyle(
    uniqueKeys.length === 1 ? 'update dictionary' : 'update dictionaries',
    style
  );

  let subject = prefix;

  for (const [index, dictionaryKey] of uniqueKeys.entries()) {
    const separator = index === 0 ? ' ' : ', ';
    const candidate = `${subject}${separator}'${dictionaryKey}'`;
    const remainingCount = uniqueKeys.length - index - 1;
    const remainingSuffix =
      remainingCount > 0 ? ` and ${remainingCount} more` : '';

    if (
      `${candidate}${remainingSuffix}`.length > COMMIT_SUBJECT_MAX_LENGTH &&
      index > 0
    ) {
      return `${subject} and ${uniqueKeys.length - index} more`;
    }

    subject = candidate;
  }

  return subject.slice(0, COMMIT_SUBJECT_MAX_LENGTH);
};

/**
 * Turns an AI answer into a single subject line matching the repository
 * style. Returns `undefined` when nothing usable is left.
 */
export const sanitizeCommitSubject = (
  rawSubject: string,
  style: CommitStyle
): string | undefined => {
  const firstLine = rawSubject
    .split('\n')
    .map((line) => line.trim())
    .find((line) => line !== '' && !line.startsWith('```'));

  if (!firstLine) return undefined;

  let subject = firstLine
    .replace(/^(commit message|subject|title)\s*:\s*/i, '')
    .replace(/^["'`]+|["'`]+$/g, '')
    .replace(/\.$/, '')
    .trim();

  if (style.isConventional && !CONVENTIONAL_COMMIT_PATTERN.test(subject)) {
    subject = applyStyle(subject, style);
  }

  if (subject.length > COMMIT_SUBJECT_MAX_LENGTH) {
    const truncated = subject.slice(0, COMMIT_SUBJECT_MAX_LENGTH);
    const lastSpaceIndex = truncated.lastIndexOf(' ');
    subject = (
      lastSpaceIndex > 0 ? truncated.slice(0, lastSpaceIndex) : truncated
    ).trim();
  }

  return subject === '' ? undefined : subject;
};

/**
 * Lines removed (`-`) and added (`+`) between two versions of a file. Order is
 * kept, moved lines are ignored: enough to describe a content change.
 */
export const summarizeLineChanges = (
  previousContent: string,
  nextContent: string
): string => {
  const countLines = (lines: string[]): Map<string, number> => {
    const counts = new Map<string, number>();
    for (const line of lines) counts.set(line, (counts.get(line) ?? 0) + 1);
    return counts;
  };

  const previousLines = previousContent.split('\n');
  const nextLines = nextContent.split('\n');
  const previousCounts = countLines(previousLines);
  const nextCounts = countLines(nextLines);

  const pickUnmatched = (
    lines: string[],
    otherCounts: Map<string, number>,
    marker: '-' | '+'
  ): string[] => {
    const remaining = new Map(otherCounts);

    return lines.flatMap((line) => {
      const count = remaining.get(line) ?? 0;

      if (count > 0) {
        remaining.set(line, count - 1);
        return [];
      }

      return line.trim() === '' ? [] : [`${marker} ${line.trim()}`];
    });
  };

  return [
    ...pickUnmatched(previousLines, nextCounts, '-'),
    ...pickUnmatched(nextLines, previousCounts, '+'),
  ].join('\n');
};

const buildChangesPrompt = (changes: CommitFileChange[]): string => {
  const prompt = changes
    .map(
      (change) =>
        `Dictionary '${change.dictionaryKey}' (${change.path}):\n${summarizeLineChanges(
          change.previousContent,
          change.nextContent
        )}`
    )
    .join('\n\n');

  return prompt.length > MAX_CHANGES_PROMPT_LENGTH
    ? `${prompt.slice(0, MAX_CHANGES_PROMPT_LENGTH)}\n[…]`
    : prompt;
};

/**
 * Resolves the AI model of the project. Only the project's own AI settings are
 * used: without them, no AI call is made.
 */
const getProjectAIConfig = async (
  project: Project
): Promise<AIConfig | undefined> => {
  const projectAIOptions = await getProjectAIOptions(project);

  if (!projectAIOptions) return undefined;

  try {
    return await getAIConfig({
      projectOptions: projectAIOptions,
      defaultOptions: AI_DEFAULT_OPTIONS,
      accessType: ['apiKey'],
    });
  } catch {
    return undefined;
  }
};

type GenerateCommitMessageOptions = {
  project: Project;
  changes: CommitFileChange[];
  recentSubjects: string[];
};

/**
 * Writes the commit subject of a batch of CMS edits: generated by the project
 * AI in the style of the recent commits when available, generic otherwise.
 */
export const generateCommitMessage = async ({
  project,
  changes,
  recentSubjects,
}: GenerateCommitMessageOptions): Promise<string> => {
  const style = detectCommitStyle(recentSubjects);
  const genericMessage = buildGenericCommitMessage(
    changes.map((change) => change.dictionaryKey),
    style
  );

  const aiConfig = await getProjectAIConfig(project);

  if (!aiConfig) return genericMessage;

  try {
    const result = await customQuery({
      aiConfig,
      system: [
        'You write git commit subjects for content edits made in a CMS.',
        'Answer with the subject line only: no body, no quotes, no markdown.',
        `Keep it under ${COMMIT_SUBJECT_MAX_LENGTH} characters, imperative mood.`,
        style.isConventional
          ? 'Use the Conventional Commits format `type(scope): subject` like the recent commits; prefer `feat` unless another type fits better.'
          : 'Do not use a `type:` prefix, the repository does not use Conventional Commits.',
        'Describe what changed in the content, not that files were updated.',
      ].join('\n'),
      messages: [
        {
          role: 'user',
          content: `Recent commit subjects of the repository:\n${recentSubjects
            .slice(0, 15)
            .map((subject) => `- ${subject}`)
            .join('\n')}\n\nChanges:\n${buildChangesPrompt(changes)}`,
        },
      ],
    });

    return (
      sanitizeCommitSubject(result?.fileContent ?? '', style) ?? genericMessage
    );
  } catch (error) {
    logger.error('Failed to generate the commit message with AI', error);
    return genericMessage;
  }
};
